//! Required Area detached copying retains actual attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><map>Fallback map<area id=list type=MiXeD nohref=legacy></map><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://area-copy.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}

#[test]
fn area_detached_copy_native_clone_preserves_independent_metadata_and_owner(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list');x.alt='A\udfffZ';x.href='leaf';x.rel='one two';var original=x.getAttributeNode('alt'),tokens=x.relList,copy=x.cloneNode(false);if(!(copy instanceof HTMLAreaElement)||copy.parentNode!==null||copy.ownerDocument!==document||copy.firstChild!==null||copy.alt!=='A\udfffZ'||copy.href!==x.href||copy.noHref!==true||copy.rel!=='one two'||copy.relList===tokens||copy.getAttributeNode('alt')===original||original.ownerElement!==x)throw 'independent native area metadata';copy.alt='copy';copy.noHref=false;copy.relList.add('three');if(x.alt!=='A\udfffZ'||x.noHref!==true||x.rel!=='one two'||copy.alt!=='copy'||copy.noHref!==false||copy.rel!=='one two three')throw 'independent copied writes';"#);}
#[test]
fn area_detached_copy_inert_import_uses_destination_base_without_source_mutation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument(''),base=owner.createElement('base');base.setAttribute('href','https://source-copy.test/root/');owner.head.appendChild(base);var source=owner.createElement('area');source.href='leaf';source.alt='A\ud800Z';source.noHref=true;var attr=source.getAttributeNode('href'),copy=document.importNode(source,false);if(!(copy instanceof HTMLAreaElement)||copy.ownerDocument!==document||copy.parentNode!==null||copy.getAttribute('href')!=='leaf'||copy.href!=='https://area-copy.test/leaf'||source.href!=='https://source-copy.test/root/leaf'||copy.alt!=='A\ud800Z'||!copy.noHref||copy.getAttributeNode('href')===attr||attr.ownerElement!==source||attr.ownerDocument!==owner)throw 'destination copy authority';copy.href='other';if(source.getAttribute('href')!=='leaf'||attr.value!=='leaf')throw 'source independent import';"#);}
#[test]
fn area_detached_copy_borrowed_deep_method_keeps_void_metadata_detached(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),method=Node.prototype.cloneNode,calls=0,copy=method.call(x,{valueOf:function(){calls++;throw 'conversion';},toString:function(){calls++;throw 'conversion';}});if(calls||copy.parentNode!==null||copy.ownerDocument!==document||copy.noHref!==true||copy.type!=='MiXeD'||copy.firstChild!==null||x.firstChild!==null||copy===x||copy.getAttributeNode('nohref')===x.getAttributeNode('nohref'))throw 'borrowed detached deep clone';"#);}

#[test]
fn area_detached_copy_deep_inert_import_and_native_clone_keep_independent_topology(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','area');source.alt='deep';source.appendChild(owner.createTextNode('text'));source.appendChild(owner.createComment('marker'));var imported=document.importNode(source,true),copy=imported.cloneNode(true);for(var node of [imported,copy]){if(node.parentNode!==null||node.ownerDocument!==document||node.alt!=='deep'||node.childNodes.length!==2||node.firstChild.data!=='text'||node.lastChild.data!=='marker'||node.firstChild.parentNode!==node||node.firstChild.ownerDocument!==document)throw 'independent deep area topology';}if(copy.firstChild===imported.firstChild||copy.firstChild===source.firstChild||source.ownerDocument!==owner||source.firstChild.ownerDocument!==owner)throw 'real deep owner identity';copy.firstChild.data='copy';if(imported.firstChild.data!=='text'||source.firstChild.data!=='text')throw 'deep copy isolation';"#);}

#[test]
fn area_detached_copy_resource_refusals_publish_nothing_and_recover(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var source=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');source.alt='retained';source.noHref=true;"}else{"var source=document.getElementById('list');source.alt='retained';"});run(&mut d,&mut f,&mut p,"var attr=source.getAttributeNode('alt'),watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,childList:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let retained=p.state.retained_limit;let nodes=p.state.node_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.execution_deadline=Some(Instant::now())};let code=if inert{"var copy=document.importNode(source,true);"}else{"var copy=source.cloneNode(true);"};let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound")||e.contains("time"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);p.state.retained_limit=retained;p.state.node_limit=nodes;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.alt!=='retained'||source.getAttributeNode('alt')!==attr||attr.ownerElement!==source||watch.takeRecords().length||document.getElementById('neighbor').value!=='seed')throw 'atomic copy refusal';");run(&mut d,&mut f,&mut p,code);run(&mut d,&mut f,&mut p,"if(!(copy instanceof HTMLAreaElement)||copy.parentNode!==null||copy.ownerDocument!==document||copy.alt!=='retained'||!copy.noHref||copy.getAttributeNode('alt')===attr||watch.takeRecords().length)throw 'fresh detached copy recovery';");assert!(!p.has_navigation_request());assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());let(a,b,c)=p.take_image_changes();assert!(a.is_empty()&&b.is_empty()&&c.is_empty());}}
}

#[test]
fn area_detached_copy_saved_child_method_checks_origin_before_copy_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var source=document.getElementById('list'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var method=frame.contentWindow.Node.prototype.cloneNode,copy=method.call(source,false);if(!(copy instanceof HTMLAreaElement)||copy.parentNode!==null)throw 'same origin native copy';");p.set_location(&crate::navigation::address("https://other-copy.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone());p.begin_job();let e=p.runtime.execute("method.call(source,false);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone()),state);p.set_location(&crate::navigation::address("https://area-copy.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"copy=method.call(source,false);if(copy.noHref!==true||copy.ownerDocument!==document||copy.parentNode!==null)throw 'fresh copy origin recovery';");}

#[test]
fn area_detached_copy_copies_nonce_unsafety_without_fabricating_source_mutation(){let(mut d,mut f,mut p)=fixture();let original=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("list")).unwrap();d.nonce_unsafe_nodes.insert(original);p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes[original]);let Value::Host(copy)=p.runtime.execute("document.getElementById('list').cloneNode(false);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("genuine copied node")};let copied=node_index(copy).unwrap();assert_ne!(copied,original);assert!(d.nonce_unsafe_nodes.contains(&copied));assert!(d.nonce_unsafe_nodes.contains(&original));assert_eq!(format!("{:?}",d.nodes[original]),before);assert!(p.state.detached_nodes.contains(&copied));assert!(!p.has_navigation_request());}
